package app.cryptoresearch.mobile;
import android.app.*;import android.content.*;import android.content.pm.ServiceInfo;import android.os.*;import org.json.*;import okhttp3.*;import okio.ByteString;import java.io.*;import java.nio.file.*;import java.util.concurrent.TimeUnit;
/** User-started, paper-only foreground session. Never stores Activity references. */
public class PaperBackgroundService extends Service {
 public static final String START="paper.START",STOP="paper.STOP";public static final int NOTICE=1301;
 public static volatile StrategyCore.Live session,transferCandidate;public static volatile boolean active=false;public static volatile String status="실행 안 됨";public static volatile double lastPrice=Double.NaN;
 public static final long LIMIT_MS=5*60*60*1000L+45*60*1000L;
 final Handler handler=new Handler(Looper.getMainLooper());OkHttpClient client;WebSocket socket;PowerManager.WakeLock wake;long startedWall,startedElapsed,lastReceive,lastSave,lastNotice;int generation;
 public static boolean owns(StrategyCore.Live p){return p!=null&&p==session;}
 public IBinder onBind(Intent i){return null;}
 public void onCreate(){super.onCreate();client=new OkHttpClient.Builder().pingInterval(20,TimeUnit.SECONDS).connectTimeout(10,TimeUnit.SECONDS).readTimeout(20,TimeUnit.SECONDS).build();NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);nm.createNotificationChannel(new NotificationChannel("paper-background","기기 백그라운드 모의매매",NotificationManager.IMPORTANCE_LOW));}
 Notification notice(){Intent stop=new Intent(this,PaperBackgroundService.class).setAction(STOP);PendingIntent end=PendingIntent.getService(this,1,stop,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);PendingIntent open=PendingIntent.getActivity(this,2,new Intent(this,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);String symbol=session==null?"":session.symbol;return new Notification.Builder(this,"paper-background").setSmallIcon(android.R.drawable.ic_media_play).setContentTitle(symbol+" 모의매매 · 백그라운드 실행").setContentText(status+" · 최대5시간45분, OS 제한 적용").setContentIntent(open).setOngoing(true).setCategory(Notification.CATEGORY_SERVICE).addAction(new Notification.Action.Builder(null,"중지",end).build()).build();}
 public int onStartCommand(Intent i,int flags,int id){if(i==null||STOP.equals(i.getAction())){finish("사용자 중지");return START_NOT_STICKY;}if(!START.equals(i.getAction())){stopSelf();return START_NOT_STICKY;}if(active)return START_NOT_STICKY;try{String symbol=i.getStringExtra("symbol");if(symbol==null||!symbol.matches("BTC|ETH|XRP|SOL|DOGE|ADA"))throw new IllegalArgumentException();if(i.getBooleanExtra("transfer",false)){StrategyCore.Live candidate=transferCandidate;transferCandidate=null;if(candidate==null||!candidate.running||!symbol.equals(candidate.symbol))throw new IllegalArgumentException();session=candidate;}else session=new StrategyCore.Live(symbol,i.getDoubleExtra("capital",1000000),i.getDoubleExtra("fee",5),i.getDoubleExtra("slip",5));status="관측 시세 연결 중";if(Build.VERSION.SDK_INT>=29)startForeground(NOTICE,notice(),ServiceInfo.FOREGROUND_SERVICE_TYPE_DATA_SYNC);else startForeground(NOTICE,notice());active=true;lastPrice=Double.NaN;startedWall=System.currentTimeMillis();startedElapsed=SystemClock.elapsedRealtime();lastReceive=0;PowerManager pm=(PowerManager)getSystemService(POWER_SERVICE);if(pm!=null){wake=pm.newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"CryptoResearch:PaperSession");wake.acquire(LIMIT_MS);}openSocket();handler.post(clock);}catch(Exception e){finish("백그라운드 실행 불가 · 앱에서 다시 확인");}return START_NOT_STICKY;}
 protected void openSocket(){if(!active||socket!=null||session==null)return;final int gen=generation;final String code="KRW-"+session.symbol;socket=client.newWebSocket(new Request.Builder().url("wss://api.upbit.com/websocket/v1").build(),new WebSocketListener(){public void onOpen(WebSocket w,Response r){w.send("[{\"ticket\":\"paper-background\"},{\"type\":\"ticker\",\"codes\":[\""+code+"\"]}]");}public void onMessage(WebSocket w,ByteString b){frame(b.utf8(),gen,code);}public void onMessage(WebSocket w,String s){frame(s,gen,code);}public void onFailure(WebSocket w,Throwable t,Response r){handler.post(()->{if(gen!=generation||!active)return;socket=null;status="수신 재연결 대기";handler.postDelayed(()->openSocket(),2000);});}public void onClosed(WebSocket w,int c,String reason){handler.post(()->{if(gen==generation&&active){socket=null;handler.postDelayed(()->openSocket(),2000);}});}});}
 void frame(String raw,int gen,String code){long received=System.currentTimeMillis();try{JSONObject j=new JSONObject(raw);if(!code.equals(j.getString("code")))return;long event=j.getLong("trade_timestamp");double price=j.getDouble("trade_price");handler.post(()->acceptFrame(gen,event,received,price));}catch(Exception ignored){}}
 void acceptFrame(int gen,long event,long received,double price){if(gen!=generation||!active||session==null)return;session.tick(event,received,System.currentTimeMillis(),price);lastReceive=received;lastPrice=price;status=session.engine.bars+"/30봉 준비 · 모의 관측";if(!session.running){finish(session.engine.reason);return;}if(System.currentTimeMillis()-lastSave>=10000)save();}
 final Runnable clock=new Runnable(){public void run(){if(!active||session==null)return;long now=System.currentTimeMillis();if(SystemClock.elapsedRealtime()-startedElapsed>=LIMIT_MS){finish("기기 실행 시간 제한");return;}if(now-(lastReceive==0?startedWall:lastReceive)>15000){finish("시세 수신 공백으로 정지");return;}if(!session.running){finish(session.engine.reason);return;}if(now-lastNotice>=5000){lastNotice=now;((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(NOTICE,notice());}handler.postDelayed(this,1000);}};
 void save(){if(session==null)return;try{File dir=getFilesDir(),tmp=new File(dir,"background-paper.tmp"),target=new File(dir,"background-paper-last.json");JSONObject obj=new JSONObject(new String(session.engine.report(),java.nio.charset.StandardCharsets.UTF_8));obj.put("session_symbol",session.symbol).put("background_status",status).put("background_active",active).put("saved_at_ms",System.currentTimeMillis());try(FileOutputStream f=new FileOutputStream(tmp)){f.write(obj.toString(2).getBytes(java.nio.charset.StandardCharsets.UTF_8));f.getFD().sync();}try{Files.move(tmp.toPath(),target.toPath(),StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException e){Files.move(tmp.toPath(),target.toPath(),StandardCopyOption.REPLACE_EXISTING);}lastSave=System.currentTimeMillis();}catch(Exception e){status="리포트 저장 실패 · 화면에서 확인";}}
 void finish(String reason){if(transferCandidate!=null){transferCandidate.pause(reason);transferCandidate=null;}active=false;status=reason;if(session!=null)session.pause(reason);save();generation++;handler.removeCallbacksAndMessages(null);if(socket!=null)socket.cancel();socket=null;if(wake!=null&&wake.isHeld())wake.release();stopForeground(STOP_FOREGROUND_REMOVE);stopSelf();}
 @Override public void onTimeout(int id,int type){finish("Android 백그라운드 시간 한도");}
 public void onDestroy(){active=false;if(session!=null&&session.running)session.pause("서비스 종료 · 잔여 모의 보유 유지");save();generation++;handler.removeCallbacksAndMessages(null);if(socket!=null)socket.cancel();if(client!=null){client.dispatcher().cancelAll();client.dispatcher().executorService().shutdown();}if(wake!=null&&wake.isHeld())wake.release();super.onDestroy();}
}
